using System;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class ConditionalAlphaTests {
 static int checks;static void Check(bool ok,string m){checks++;if(!ok)throw new Exception(m);}static void Near(double a,double b,string m){Check(Math.Abs(a-b)<1e-9,m+": "+a+" != "+b);}
 static Track E(bool raw=true){return new Track{id="e",kind="emitter",start=0,end=0,count=1,x=100,y=100,speed=0,life=100,advancedBullets=true,rawAlpha=raw};}
 static EditorState Scene(params Track[] ts){var s=new EditorState{duration=600,tracks=ts.ToList()};Motion.Normalize(s);return s;}static SimBullet B(BulletWorld w){return w.bullets.Single(b=>b.generation==0);}
 public sealed class Oracle {public List<Case> cases;} public sealed class Case {public int fadeOutStartAge,expectedDeathAge;public List<Row> sequence;} public sealed class Row {public int age;public double rawAlpha,visibleAlpha;public bool destroy;}
 static string SourceFile([System.Runtime.CompilerServices.CallerFilePath]string file=""){return file;}
 static void Main(){
  var t=E();t.bulletActions.Add(new BulletAction{type="alpha",start=0,duration=2,expression="alpha+0.04",condition="alpha<=1"});var w=new BulletWorld(Scene(t));w.Seek(0);Near(B(w).alpha,1.04,"raw overshoot");w.Seek(1);Near(B(w).alpha,1.04,"raw condition halts");t.bulletActions.Add(new BulletAction{type="alpha",start=2,duration=0,expression="alpha-0.04"});w=new BulletWorld(Scene(t));w.Seek(2);Near(B(w).alpha,1,"raw falls back");
  t=E(false);t.bulletActions.Add(new BulletAction{type="alpha",duration=3,expression="alpha+0.04"});w=new BulletWorld(Scene(t));w.Seek(2);Near(B(w).alpha,1,"legacy clamped");
  t=E();t.bulletActions.Add(new BulletAction{type="speed",duration=8,condition="age>=2",expression="speed+1",once=true});w=new BulletWorld(Scene(t));w.Seek(1);Near(B(w).speed,0,"false retains once");w.Seek(2);Near(B(w).speed,1,"true fires");w.Seek(4);Near(B(w).speed,1,"once holds");w.Seek(1);Near(B(w).speed,0,"reverse reconstruct");w.Seek(4);Near(B(w).speed,1,"replay same");var clone=B(w).Clone();Check(clone.firedActions.SetEquals(B(w).firedActions),"checkpoint markers cloned");clone.firedActions.Clear();Check(B(w).firedActions.Count==1,"clone markers independent");
  var reset=new Track{id="reset",kind="control",start=3,end=3,eventPreset="reset-motion",eventRestoreBirth=false,eventDisableMotion=false,eventResetLife=true,eventLife=100};w=new BulletWorld(Scene(t,reset));w.Seek(7);Near(B(w).speed,0,"reset age does not replay consumed once");
  t=E();t.bulletActions.Add(new BulletAction{type="alpha",duration=8,expression="alpha-0.4"});t.bulletActions.Add(new BulletAction{type="clear",duration=8,condition="alpha<=0"});w=new BulletWorld(Scene(t));w.Seek(1);Check(w.bullets.Count==1,"clear false");w.Seek(2);Check(w.bullets.Count==0,"clear sees preceding alpha");
  t=E();t.bulletActions.Add(new BulletAction{type="clear",duration=8});w=new BulletWorld(Scene(t));w.Seek(0);Check(w.bullets.Count==0,"legacy clear at start");
  t=E();t.bulletActions.Add(new BulletAction{type="alpha",duration=0,to=1.04});t.bulletActions.Add(new BulletAction{type="split",duration=4,condition="age>=2",once=true,count=1,childSpeed=2});w=new BulletWorld(Scene(t));w.Seek(1);Check(w.bullets.Count==1,"split false");w.Seek(2);var child=w.bullets.Single(b=>b.generation==1);Near(child.alpha,1.04,"plain split raw alpha");Check(child.commands.Count==0&&child.firedActions.Count==0,"plain child fresh markers");w.Seek(4);Check(w.bullets.Count==2,"split once");
  t=E();var target=E();target.id="target";target.templateOnly=true;t.bulletActions.Add(new BulletAction{type="spawn",templateId="target",duration=5,condition="alpha>1",once=true});t.bulletActions.Insert(0,new BulletAction{type="alpha",start=2,duration=0,to=1.04});w=new BulletWorld(Scene(t,target));w.Seek(1);Check(w.bullets.Count==1,"spawn false");w.Seek(2);Check(w.bullets.Count==2,"spawn late true");w.Seek(4);Check(w.bullets.Count==2,"spawn once");
  t=E();t.bulletActions.Add(new BulletAction{type="alpha",duration=0,to=1.04});t.deathEffect="fade";t.deathFrames=10;t.life=10;w=new BulletWorld(Scene(t));w.Seek(5);Near(B(w).alpha,1.04,"death keeps logic");Near(B(w).Sample(5).alpha,.52,"death factors before clamp");Near(B(w).Sample(5).alpha*.55,.286,"trail factor preserves raw");
  t=E();var c=new Track{id="c",kind="control",start=0,end=0,controlAction="alpha",controlExpression="alpha+0.04"};w=new BulletWorld(Scene(t,c));w.Seek(0);Near(B(w).alpha,1.04,"control current alpha");
  t=E();t.bulletActions.Add(new BulletAction{type="speed",condition="age>2",once=true});var s=Scene(t);var json=new JavaScriptSerializer();var restored=json.Deserialize<EditorState>(json.Serialize(s));Motion.Normalize(restored);Check(restored.tracks[0].rawAlpha&&restored.tracks[0].bulletActions[0].once,"JSON fields");Check(BulletSystem.CloneTracks(s.tracks)[0].bulletActions[0].condition=="age>2","copy fields");Check(s.Snapshot().tracks[0].rawAlpha,"snapshot field");Check(TrackPreset.Capture("raw",s.tracks,50).Instantiate(0,50)[0].rawAlpha,"preset field");Check(!json.Deserialize<Track>("{}").rawAlpha&&!json.Deserialize<BulletAction>("{}").once,"old defaults");
  t=E();t.bulletActions.Add(new BulletAction{type="speed",duration=10,condition="frame>=global.release+at(i,1)",once=true,expression="speed+1"});var variable=new Track{id="v",kind="variable",start=3,end=3,variableName="release",variableDefault=1000000000,variableExpression="frame"};s=Scene(t,variable);Check(GlobalVariables.References(t).Contains("release"),"condition global references");w=new BulletWorld(s);w.Seek(3);Near(B(w).speed,0,"global condition before delay");w.Seek(4);Near(B(w).speed,1,"global condition true");w.Seek(2);Near(B(w).speed,0,"global condition reverse");GlobalVariables.ReplaceReference(t,"release","renamed");Check(t.bulletActions[0].condition.Contains("global.renamed"),"condition global rename");Near(RandomExpression.Evaluate("at(alpha<=1,1,alpha+.04)",1,"x",new ExpressionContext{alpha=1}),1.04,"comparison at combination");
  t=E();t.bulletActions.Add(new BulletAction{type="speed",start=1,duration=0,once=true,to=8});c=new Track{id="once|e|0",kind="control",start=0,end=0,controlAction="speed",controlValue=0};w=new BulletWorld(Scene(t,c));w.Seek(2);Near(B(w).speed,8,"once markers cannot collide with control IDs");Check(B(w).commands.Contains(c.id)&&B(w).firedActions.Count==1,"independent once and control sets");
  var oracle=new JavaScriptSerializer().Deserialize<Oracle>(System.IO.File.ReadAllText(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(SourceFile()),"..","..","tests","raw-alpha-oracle.json")));
  foreach(var test in oracle.cases){t=E();t.alpha=0;t.bulletActions.Add(new BulletAction{type="alpha",duration=100,condition="age<"+test.fadeOutStartAge,expression="(alpha<=1)*(alpha+1/25)+(alpha>1)"});t.bulletActions.Add(new BulletAction{type="alpha",duration=100,condition="age>="+test.fadeOutStartAge,expression="alpha-1/25"});t.bulletActions.Add(new BulletAction{type="clear",duration=100,condition="alpha<=0"});w=new BulletWorld(Scene(t));foreach(var row in test.sequence){w.Seek(row.age);if(row.destroy)Check(w.bullets.Count==0,"oracle death "+test.fadeOutStartAge);else {Near(B(w).alpha,row.rawAlpha,"oracle raw");Near(Math.Max(0,Math.Min(1,B(w).alpha)),row.visibleAlpha,"oracle visible");}}}
  Console.WriteLine("PASS ConditionalAlpha "+checks+" checks");
 }
}
